input.command:
OP=$(cat <<'__T__'
${opened}
__T__
); OF=$(cat <<'__T__'
${open_file}
__T__
); GO=$(cat <<'__G__'
${grep_out}
__G__
); IX=$(cat <<'__I__'
${index}
__I__
); OF=$(printf '%s' "$OF" | tr -d '[:space:]'); is_open() { printf '%s\n' "$OP" | grep -qx -- "$1"; }; CH=""; if [ -n "$OF" ] && ! is_open "$OF" && [ -f "${docs_dir}/$OF" ]; then CH="$OF"; NOTE="ok: $OF"; fi; if [ -z "$CH" ]; then for f in $(printf '%s\n' "$GO" | sed -n '/HITS PER FILE/,/MATCHING LINES/p' | grep -E '^doc_[0-9]+\.txt:[0-9]+$' | sort -t: -k2 -nr | cut -d: -f1); do if ! is_open "$f"; then CH="$f"; NOTE="substituted (choice '$OF' was already opened or invalid): $f, the unopened file with most grep hits"; break; fi; done; fi; if [ -z "$CH" ]; then for f in $(printf '%s\n' "$IX" | grep -oE '^doc_[0-9]+\.txt'); do if ! is_open "$f"; then CH="$f"; NOTE="substituted (choice '$OF' was already opened or invalid): $f, the first unopened file in index"; break; fi; done; fi; if [ -z "$CH" ]; then exit 1; fi; printf '%s' "$CH"

cd "${docs_dir}" && PAT=$(cat <<'__T__'
${grep_pattern}
__T__
); echo "=== HITS PER FILE (file:count) for pattern: $PAT ==="; grep -c -i -E -- "$PAT" *.txt 2>/dev/null | grep -v ':0$' | sort -t: -k2 -nr | head -30; echo "=== MATCHING LINES (file:line:text, first 120) ==="; grep -n -i -E -- "$PAT" *.txt 2>/dev/null | cut -c1-220 | head -120; echo "=== END ==="

OF=$(cat <<'__T__'
${open_file}
__T__
); OF=$(printf '%s' "$OF" | tr -d '[:space:]'); F="${docs_dir}/$OF"; if [ ! -f "$F" ]; then echo "NO SUCH FILE: $OF" >&2; exit 1; fi; echo "===== $OF ($(wc -c < "$F" | tr -d ' ') bytes) ====="; head -c 60000 "$F"; echo; echo "===== END OF $OF ====="

OP=$(cat <<'__T__'
${opened}
__T__
); OF=$(cat <<'__T__'
${open_file}
__T__
); printf '%s\n%s\n' "$OP" "$OF" | grep -v '^none$' | awk 'NF' | awk '!seen[$0]++'

EV=$(cat <<'__E__'
${evidence}
__E__
); NF=$(cat <<'__N__'
${new_findings}
__N__
); OF=$(cat <<'__T__'
${open_file}
__T__
); { if [ "$EV" != "none" ]; then printf '%s\n' "$EV"; fi; printf '\n=== page %s: %s ===\n%s\n' "${open_count}" "$OF" "$NF"; }

SCH=$(cat <<'__S__'
${schema}
__S__
); CMD=$(cat <<'__C__'
${calc_cmd}
__C__
); if [ "${calc_count}" -lt 2 ] && printf '%s' "$SCH" | grep -q -i -E 'type:[^;]*(count|list|threshold|ranking|superlative|ordinal)' && printf '%s' "$CMD" | grep -q -E '^[[:space:]]*(printf|echo)[[:space:]]'; then echo 'REJECTED: for a count, list, threshold, ranking or ordinal question the answer must be computed from the ledger rows in the script (a python list that is filtered and counted or compared), not printed as a bare value'; exit 1; fi; bash -c "$CMD"
